import random

from txn_simulator import Workload
from workloads import WORKLOAD_1, WORKLOAD_2, WORKLOAD_3

# EVOLVE-BLOCK-START

def get_best_schedule(workload, num_seqs):
    """Decompose read/write-conflict components with sparse connected-components, then simulator-search each component."""
    n = workload.num_txns
    if n == 0:
        return 0, []

    # Find the workload's transaction text without relying on one particular
    # Workload implementation.  A component split is safe only when every
    # cross-component pair has no read/write or write/write conflict.
    def transaction_texts(obj, expected):
        candidates = []
        for value in vars(obj).values():
            if isinstance(value, dict):
                values = list(value.values())
            elif isinstance(value, (list, tuple)):
                values = list(value)
            else:
                continue
            if len(values) == expected and all(isinstance(x, str) for x in values):
                candidates.append(values)
        for values in candidates:
            if any(("r-" in text or "w-" in text) for text in values):
                return values
        return None

    texts = transaction_texts(workload, n)
    if texts is not None and n > 1:
        try:
            from scipy.sparse import lil_matrix
            from scipy.sparse.csgraph import connected_components

            # For each key retain whether each transaction writes it.  Read/read
            # sharing deliberately creates no edge.
            by_key = {}
            for txn, text in enumerate(texts):
                accesses = {}
                for token in text.split():
                    if len(token) >= 3 and token[0] in "rw" and token[1] == "-":
                        accesses[token[2:]] = accesses.get(token[2:], False) or token[0] == "w"
                for key, writes in accesses.items():
                    by_key.setdefault(key, []).append((txn, writes))

            graph = lil_matrix((n, n), dtype="int8")
            for users in by_key.values():
                for left in range(len(users)):
                    a, aw = users[left]
                    for right in range(left):
                        b, bw = users[right]
                        if aw or bw:
                            graph[a, b] = graph[b, a] = 1

            count, labels = connected_components(
                graph.tocsr(), directed=False, return_labels=True)
            if count > 1:
                groups = [[i for i in range(n) if labels[i] == label]
                          for label in range(count)]

                # Guard against simulators with an undocumented global ordering
                # effect.  Swapping whole independent blocks must be neutral
                # before recursive component optimization is trusted.
                forward = [item for group in groups for item in group]
                backward = [item for group in reversed(groups) for item in group]
                if workload.get_opt_seq_cost(forward) == workload.get_opt_seq_cost(backward):
                    class ComponentWorkload:
                        """Map local component permutations back to parent transaction ids."""
                        def __init__(self, parent, members, source):
                            self.parent = parent
                            self.members = members
                            self.num_txns = len(members)
                            self.transactions = [source[i] for i in members]

                        def get_opt_seq_cost(self, sequence):
                            return self.parent.get_opt_seq_cost(
                                [self.members[i] for i in sequence])

                    assembled = []
                    for group in groups:
                        child = ComponentWorkload(workload, group, texts)
                        _, local_order = get_best_schedule(child, num_seqs)
                        assembled.extend(group[i] for i in local_order)
                    return workload.get_opt_seq_cost(assembled), assembled
        except (ImportError, AttributeError, TypeError, ValueError):
            # Retain the original global search when transaction text or scipy
            # is unavailable rather than risking an unsound decomposition.
            pass

    # Simulator evaluations are the only reliable objective, but caching every
    # sampled relocation can consume substantial memory on large workloads.
    # Keep a bounded cache: repeated nearby schedules still benefit, while
    # long searches remain robust under the evaluator's memory limits.
    cache = {}
    cache_limit = 30000
    evaluations = [0]

    def cost(seq):
        """Return authoritative simulator makespan while counting uncached calls."""
        key = tuple(seq)
        value = cache.get(key)
        if value is None:
            evaluations[0] += 1
            value = workload.get_opt_seq_cost(seq)
            if len(cache) >= cache_limit:
                cache.clear()
            cache[key] = value
        return value

    if n <= 8:
        import itertools
        best = min(itertools.permutations(range(n)), key=cost)
        return cost(best), list(best)

    # A fixed seed makes improvements reproducible while still providing
    # randomized candidate diversity for large transaction sets.
    rng = random.Random(7919 + 97 * n)
    width = max(8, min(20, max(1, num_seqs) * 2))
    sample_size = n if n <= 36 else 24

    # Retain competing low-cost prefixes so a locally attractive early
    # conflict orientation cannot force the entire schedule into a poor basin.
    beam = [([], tuple(range(n)))]
    for _ in range(n):
        expanded = []
        for prefix, remaining in beam:
            choices = remaining
            if len(remaining) > sample_size:
                choices = tuple(rng.sample(list(remaining), sample_size))
            for txn in choices:
                seq = prefix + [txn]
                rest = tuple(item for item in remaining if item != txn)
                expanded.append((cost(seq), seq, rest))

        expanded.sort(key=lambda item: item[0])
        beam = []
        seen = set()
        for _, seq, rest in expanded:
            marker = tuple(seq)
            if marker not in seen:
                beam.append((seq, rest))
                seen.add(marker)
                if len(beam) == width:
                    break

    candidates = [(cost(seq), seq) for seq, _ in beam]

    # Add independent greedy schedules, which supply useful diversity when
    # prefix-only beam pruning rejects a transaction that pays off later.
    starts = list(range(n))
    rng.shuffle(starts)
    for start in starts[:max(1, min(n, num_seqs))]:
        seq = [start]
        remaining = [item for item in range(n) if item != start]
        while remaining:
            choices = remaining if len(remaining) <= sample_size else rng.sample(
                remaining, sample_size)
            txn = min(choices, key=lambda item: cost(seq + [item]))
            seq.append(txn)
            remaining.remove(txn)
        candidates.append((cost(seq), seq))

    candidates.sort(key=lambda item: item[0])
    best_cost, best_seq = candidates[0]

    def descend(initial):
        """Use relocation descent while traversing a few equal-cost plateaus."""
        seq = initial[:]
        current = cost(seq)
        local_best_cost, local_best_seq = current, seq[:]
        seen = {tuple(seq)}

        # Makespan values are coarse and many distinct conflict orientations
        # tie.  Strict descent stops on such a plateau even when an improving
        # orientation is only one neutral relocation away.  Prefer improving
        # insertions, but retain a small unbiased sample of unseen ties when
        # there is no improvement.
        for _ in range(min(3 * n, 30)):
            move_cost, move_seq = current, None
            equal_moves = []
            if n <= 28:
                positions = range(n)
                destination_count = n
            else:
                positions = rng.sample(range(n), min(n, 24))
                destination_count = min(n, 24)

            for old_pos in positions:
                reduced = seq[:old_pos] + seq[old_pos + 1:]
                if n <= 28:
                    destinations = range(n)
                else:
                    destinations = rng.sample(range(n), destination_count)

                for new_pos in destinations:
                    trial = reduced[:new_pos] + [seq[old_pos]] + reduced[new_pos:]
                    marker = tuple(trial)
                    if marker in seen:
                        continue
                    trial_cost = cost(trial)
                    if trial_cost < move_cost:
                        move_cost, move_seq = trial_cost, trial
                    elif trial_cost == current:
                        if len(equal_moves) < 12:
                            equal_moves.append(trial)
                        elif rng.randrange(len(equal_moves) + 1) < 12:
                            equal_moves[rng.randrange(12)] = trial

            if move_seq is not None:
                seq, current = move_seq, move_cost
            elif equal_moves:
                seq = rng.choice(equal_moves)
                current = cost(seq)
            else:
                break

            seen.add(tuple(seq))
            if current < local_best_cost:
                local_best_cost, local_best_seq = current, seq[:]

        # Neutral movement can expose a useful adjacent conflict reversal in
        # the best basin reached during plateau traversal.
        for _ in range(3):
            changed = False
            for pos in range(n - 1):
                trial = local_best_seq[:]
                trial[pos], trial[pos + 1] = trial[pos + 1], trial[pos]
                trial_cost = cost(trial)
                if trial_cost < local_best_cost:
                    local_best_seq, local_best_cost = trial, trial_cost
                    changed = True
            if not changed:
                break
        return local_best_cost, local_best_seq

    # Build an explicit conflict-pair list solely to focus the neighborhood.
    # It is never used as a surrogate objective: every accepted candidate is
    # still ranked by the simulator's full makespan.
    conflict_pairs = set()
    if texts is not None:
        users = {}
        for txn, text in enumerate(texts):
            seen_accesses = {}
            for token in text.split():
                if len(token) >= 3 and token[0] in "rw" and token[1] == "-":
                    key = token[2:]
                    seen_accesses[key] = seen_accesses.get(key, False) or token[0] == "w"
            for key, writes in seen_accesses.items():
                users.setdefault(key, []).append((txn, writes))
        for item_users in users.values():
            for i in range(len(item_users)):
                for j in range(i):
                    a, aw = item_users[i]
                    b, bw = item_users[j]
                    if aw or bw:
                        conflict_pairs.add((min(a, b), max(a, b)))

    # Opaque workloads retain a complete-pair fallback, preserving correctness.
    if not conflict_pairs:
        conflict_pairs = {(i, j) for i in range(n) for j in range(i + 1, n)}
    conflict_pairs = list(conflict_pairs)
    conflict_set = set(conflict_pairs)

    from collections import deque

    def tabu_refine(initial, incumbent_cost, incumbent_seq):
        """Direct simulator-scored tabu search using swaps and conflict block moves."""
        seq = initial[:]
        current = cost(seq)
        if current < incumbent_cost:
            incumbent_cost, incumbent_seq = current, seq[:]

        # A tabu entry represents a recently reversed conflict orientation.
        tabu = deque(maxlen=max(12, min(80, 2 * n)))
        tabu_set = set()
        budget = 55000

        def remember(pairs):
            for pair in pairs:
                if pair not in conflict_set:
                    continue
                if len(tabu) == tabu.maxlen:
                    tabu_set.discard(tabu.popleft())
                tabu.append(pair)
                tabu_set.add(pair)

        iterations = 0
        while evaluations[0] < budget and iterations < max(30, 5 * n):
            iterations += 1
            positions = {txn: pos for pos, txn in enumerate(seq)}
            proposals = {}
            pair_sample = conflict_pairs if len(conflict_pairs) <= 36 else rng.sample(
                conflict_pairs, 36)

            # Conflict-bearing arbitrary and adjacent swaps directly reverse
            # precedence directions that can alter the operation DAG.
            for a, b in pair_sample:
                i, j = positions[a], positions[b]
                trial = seq[:]
                trial[i], trial[j] = trial[j], trial[i]
                proposals[tuple(trial)] = [(a, b)]

                if abs(i - j) > 1:
                    trial = seq[:]
                    if i > j:
                        i, j = j, i
                    trial[i], trial[i + 1] = trial[i + 1], trial[i]
                    proposals[tuple(trial)] = [(seq[i], seq[i + 1])]

            # Large neighborhoods relocate 2/3 consecutive transactions
            # around another conflict participant, changing many directions.
            for _ in range(min(18, max(6, n // 2))):
                a, b = conflict_pairs[rng.randrange(len(conflict_pairs))]
                anchor = positions[a] if rng.randrange(2) else positions[b]
                size = 2 if n < 7 or rng.randrange(2) else 3
                start = max(0, min(n - size, anchor - rng.randrange(size)))
                block = seq[start:start + size]
                rest = seq[:start] + seq[start + size:]
                other = b if a in block else a
                target = positions[other]
                if target > start:
                    target -= size
                target = max(0, min(len(rest), target + rng.randrange(-2, 3)))
                trial = rest[:target] + block + rest[target:]
                crossed = [(min(x, y), max(x, y))
                           for x in block
                           for y in seq[min(start, target):max(start, target) + size]
                           if x != y]
                proposals[tuple(trial)] = crossed

            chosen_cost, chosen_seq, chosen_pairs = float("inf"), None, None
            for trial_key, reversed_pairs in proposals.items():
                if trial_key == tuple(seq):
                    continue
                trial = list(trial_key)
                value = cost(trial)
                tabu_move = any(pair in tabu_set for pair in reversed_pairs)
                # Aspiration ensures tabu status can never reject an incumbent
                # improvement. Otherwise select the best admissible worsening
                # move too, allowing traversal out of local minima.
                if tabu_move and value >= incumbent_cost:
                    continue
                if value < chosen_cost:
                    chosen_cost, chosen_seq, chosen_pairs = value, trial, reversed_pairs

            if chosen_seq is None:
                tabu.clear()
                tabu_set.clear()
                continue

            seq, current = chosen_seq, chosen_cost
            remember(chosen_pairs)
            if current < incumbent_cost:
                incumbent_cost, incumbent_seq = current, seq[:]

            # Periodically perturb a dense local region. Several permutations
            # are scored and the best becomes the next tabu state even when it
            # is not globally improving.
            if iterations % max(8, n // 2) == 0 and evaluations[0] < budget:
                dense_start, dense_score = 0, -1
                block_size = min(5, n)
                for start in range(n - block_size + 1):
                    block_set = set(seq[start:start + block_size])
                    score = sum(a in block_set and b in block_set
                                for a, b in conflict_pairs)
                    if score > dense_score:
                        dense_start, dense_score = start, score
                local_best, local_cost = seq, current
                for _ in range(8):
                    trial = seq[:]
                    part = trial[dense_start:dense_start + block_size]
                    rng.shuffle(part)
                    trial[dense_start:dense_start + block_size] = part
                    value = cost(trial)
                    if value < local_cost:
                        local_best, local_cost = trial, value
                seq, current = local_best, local_cost
                if current < incumbent_cost:
                    incumbent_cost, incumbent_seq = current, seq[:]

        return incumbent_cost, incumbent_seq

    # Multiple beam/greedy seeds give tabu search distinct conflict
    # orientations. The separate incumbent survives deliberately worsening
    # transitions within every tabu trajectory.
    for _, initial in candidates[:min(6, len(candidates))]:
        best_cost, best_seq = tabu_refine(initial, best_cost, best_seq)

    return best_cost, best_seq

# EVOLVE-BLOCK-END

def get_random_costs():
    workload_size = 100
    workload = Workload(WORKLOAD_1)

    makespan1, schedule1 = get_best_schedule(workload, 10)
    cost1 = workload.get_opt_seq_cost(schedule1)

    workload2 = Workload(WORKLOAD_2)
    makespan2, schedule2 = get_best_schedule(workload2, 10)
    cost2 = workload2.get_opt_seq_cost(schedule2)

    workload3 = Workload(WORKLOAD_3)
    makespan3, schedule3 = get_best_schedule(workload3, 10)
    cost3 = workload3.get_opt_seq_cost(schedule3)
    print(cost1, cost2, cost3)
    return cost1 + cost2 + cost3, [schedule1, schedule2, schedule3]


if __name__ == "__main__":
    makespan, schedule = get_random_costs()
    print(f"Makespan: {makespan}")
